import React, { useState } from "react";
import { Copy, X, Share2, Heart, Bookmark, Clock, DollarSign } from "lucide-react";

const JobCard = ({ job }) => {
  const [showPopup, setShowPopup] = useState(false);
  const jobURL = window.location.href; // Replace with actual job URL

  const handleCopyLink = () => {
    navigator.clipboard.writeText(jobURL);
    alert("Link copied to clipboard!");
  };

  return (
    <div className="bg-black text-white rounded-xl shadow-lg flex items-center p-6 space-x-6 w-full">
      {/* Job Image */}
      {job.fileAttachment && (
        <img src={job.fileAttachment} alt={job.title} className="w-40 h-40 object-cover rounded-lg" />
      )}

      <div className="flex-1">
        <h3 className="text-xl font-semibold">{job.title}</h3>
        <p className="text-gray-300 mt-1">{job.description}</p>

        <div className="flex flex-wrap mt-3 space-x-2">
          {job.skillsRequired.map((skill, index) => (
            <span key={index} className="bg-gray-800 px-3 py-1 rounded-full text-sm">{skill}</span>
          ))}
        </div>

        <div className="flex items-center mt-4 space-x-6 text-gray-400">
          <span className="flex items-center"><DollarSign size={16} className="mr-1" /> ${job.budget}</span>
          <span className="flex items-center"><Clock size={16} className="mr-1" /> {job.timeline}</span>
          <span className="flex items-center"><Heart size={16} className="mr-1" /> {job.likes} Likes</span>
        </div>

        <div className="flex items-center space-x-4 mt-4">
          <button className="flex items-center bg-red-600 px-4 py-2 rounded-lg">
            <Heart size={18} className="mr-2" /> Like
          </button>
          <button className="flex items-center bg-gray-700 px-4 py-2 rounded-lg">
            <Bookmark size={18} className="mr-2" /> Bookmark
          </button>
          <button className="flex items-center bg-blue-600 px-4 py-2 rounded-lg" onClick={() => setShowPopup(true)}>
            <Share2 size={18} className="mr-2" /> Share
          </button>
          <button className="bg-green-600 px-4 py-2 rounded-lg">Apply Now</button>
        </div>
      </div>

      {/* Share Popup */}
      {showPopup && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-75">
          <div className="bg-gray-900 p-6 rounded-lg w-80 text-center">
            <div className="flex justify-between">
              <h4 className="text-lg font-semibold">Share this Job</h4>
              <button onClick={() => setShowPopup(false)} className="text-gray-400 hover:text-white"><X size={20} /></button>
            </div>
            <button onClick={handleCopyLink} className="flex items-center bg-gray-700 px-4 py-2 rounded-lg w-full mt-3">
              <Copy size={18} className="mr-2" /> Copy Link
            </button>
            <a href={`https://wa.me/?text=${encodeURIComponent(jobURL)}`} target="_blank" rel="noopener noreferrer" className="flex items-center bg-green-600 px-4 py-2 rounded-lg w-full mt-3">
              📱 Share on WhatsApp
            </a>
            <a href={`https://twitter.com/intent/tweet?text=${encodeURIComponent(job.title + " - " + jobURL)}`} target="_blank" rel="noopener noreferrer" className="flex items-center bg-blue-600 px-4 py-2 rounded-lg w-full mt-3">
              🐦 Share on X (Twitter)
            </a>
          </div>
        </div>
      )}
    </div>
  );
};

export default JobCard;
